      X("I suggest that she goes home.", "I suggest that she go home.", "Без -s.", acc=["I suggest that she should go home.", "I suggest she go home."], tp="subjunctive"),
      X("It's important that he is here.", "It's important that he be here.", "Be.", acc=["It's important that he should be here.", "It is important that he be here."], tp="subjunctive"),
