# ============ 6. Модальные: нюансы ============
UNITS.append(unit(6, "grammar", "Modals: shades of meaning", "Модальні: відтінки значень", "Модальные: оттенки значений",
  rule(("be bound to · be likely to · may well · can't possibly · shall · need not · will / would — звички й характер", "be bound to · be likely to · may well · can't possibly · shall · need not · will / would — привычки и характер"),
       "C1 — це відтінки: may well (цілком можливо) сильніше за may; be bound to — «неодмінно»; He will leave his socks everywhere — дратівлива звичка; She would always sing in the kitchen — звичка в минулому.",
       "C1 — это оттенки: may well (вполне возможно) сильнее, чем may; be bound to — «непременно»; He will leave his socks everywhere — раздражающая привычка; She would always sing in the kitchen — привычка в прошлом.",
       [("It's bound to rain — it always does on holidays.", "Неодмінно піде дощ — так завжди у свята.", "Обязательно пойдёт дождь — так всегда в праздники."),
        ("You need not worry.", "Вам не варто хвилюватися.", "Вам незачем беспокоиться."),
        ("My grandpa would tell us stories every night.", "Дідусь щовечора розповідав нам історії.", "Дедушка каждый вечер рассказывал нам истории.")]),
  [V("be bound to", "/biː ˈbaʊnd tə/", "неодмінно, напевно", "обязательно, наверняка", "He's bound to be late."),
   V("be likely to", "/biː ˈlaɪkli tə/", "ймовірно", "вероятно", "Prices are likely to rise."),
   V("be unlikely to", "/biː ʌnˈlaɪkli tə/", "навряд чи", "вряд ли", "She's unlikely to agree."),
   V("may well", "/meɪ ˈwel/", "цілком можливо", "вполне возможно", "You may well be right."),
   V("might as well", "/maɪt əz ˈwel/", "можна й (немає причин не)", "можно и (нет причин не)", "We might as well go home."),
   V("can't possibly", "/kɑːnt ˈpɒsəbli/", "аж ніяк не може", "никак не может", "I can't possibly finish today."),
   V("shall", "/ʃæl/", "(офіційне) зобов'язаний; запропонувати", "(официальное) обязан; предложить", "Shall I open the window?"),
   V("need not / needn't", "/niːd nɒt/", "не обов'язково", "не обязательно", "You needn't come."),
   V("be to", "/biː tə/", "мати (за наказом / планом)", "должен (по приказу / плану)", "You are to report at 9."),
   V("will (habit)", "/wɪl/", "(дратівлива звичка)", "(раздражающая привычка)", "He will keep interrupting!"),
   V("would (past habit)", "/wʊd/", "бувало, (звичка в минулому)", "бывало, (привычка в прошлом)", "We would play outside for hours."),
   V("dare", "/deə/", "сміти, наважитися", "сметь, осмелиться", "How dare you!")],
  [
   lesson("Shades of probability", "Відтінки ймовірності", "Оттенки вероятности",
     rule(("bound to (≈100%) · likely to · may well · may / might · unlikely to · can't possibly (≈0%) · might as well — «можна й…»", "bound to (≈100%) · likely to · may well · may / might · unlikely to · can't possibly (≈0%) · might as well — «можно и…»"),
          "Шкала впевненості: She's bound to win → She's likely to win → She may well win → She might win → She's unlikely to win → She can't possibly win. Might as well — нема кращого варіанту: The shop is closed, we might as well go home.",
          "Шкала уверенности: She's bound to win → She's likely to win → She may well win → She might win → She's unlikely to win → She can't possibly win. Might as well — нет лучшего варианта: The shop is closed, we might as well go home.",
          [("Don't worry, he's bound to call.", "Не хвилюйся, він обов'язково подзвонить.", "Не волнуйся, он обязательно позвонит."),
           ("Prices are likely to go up next year.", "Ціни, ймовірно, зростуть наступного року.", "Цены, вероятно, вырастут в следующем году."),
           ("There's nothing on TV — we might as well go to bed.", "По телевізору нічого — можна й спати лягати.", "По телевизору ничего — можно и спать ложиться.")]),
     [C("She studied so hard — she's ___ to pass.", ["bound", "unlikely", "possible"], "bound", "Майже напевно → bound to.", "Почти наверняка → bound to.", tp="modals-nuance"),
      C("It's very cloudy. It's ___ to rain later.", ["likely", "unlikely", "can't"], "likely", "Likely to.", tp="modals-nuance"),
      C("You may ___ be right. I hadn't thought of that.", ["well", "good", "also"], "well", "May well — цілком можливо.", "May well — вполне возможно.", tp="modals-nuance"),
      C("He's very shy. He's ___ to speak at the meeting.", ["unlikely", "bound", "likely"], "unlikely", "Навряд чи → unlikely.", "Вряд ли → unlikely.", tp="modals-nuance"),
      C("The bus has gone. We might ___ walk.", ["as well", "well", "also"], "as well", "Might as well.", tp="modals-nuance"),
      C("I can't ___ eat all this!", ["possibly", "possible", "maybe"], "possibly", "Can't possibly.", tp="modals-nuance"),
      M([("bound to", "≈ 100%"), ("likely to", "≈ 70%"), ("unlikely to", "≈ 20%"), ("can't possibly", "≈ 0%")], "Шкала ймовірності.", "Шкала вероятности.", tp="modals-nuance"),
      X("He's bound to being late.", "He's bound to be late.", "Bound to + дієслово.", "Bound to + глагол.", tp="modals-nuance"),
      T("Він, імовірно, погодиться.", "Он, вероятно, согласится.", "He's likely to agree.", "Likely to.", acc=["He is likely to agree.", "He'll probably agree.", "He will probably agree."], tp="modals-nuance"),
     ]),
   lesson("Formal modals", "Офіційні модальні", "Официальные модальные",
     rule(("shall (пропозиція / правило) · need not (не обов'язково) · be to (наказ, план) · may (офіційний дозвіл) · How dare…!", "shall (предложение / правило) · need not (не обязательно) · be to (приказ, план) · may (официальное разрешение) · How dare…!"),
          "Shall I…? / Shall we…? — пропозиція. У документах shall — обов'язок: The tenant shall pay rent monthly. You are to arrive by 9 — інструкція. You need not reply — можна не відповідати.",
          "Shall I…? / Shall we…? — предложение. В документах shall — обязанность: The tenant shall pay rent monthly. You are to arrive by 9 — инструкция. You need not reply — можно не отвечать.",
          [("Shall we start?", "Почнімо?", "Начнём?"),
           ("All visitors are to sign in at reception.", "Усі відвідувачі мають зареєструватися на рецепції.", "Все посетители должны зарегистрироваться на ресепшене."),
           ("You need not bring anything.", "Нічого не треба приносити.", "Ничего не нужно приносить.")]),
     [C("___ I help you with your bags?", ["Shall", "Will", "Do"], "Shall", "Пропозиція → Shall I.", "Предложение → Shall I.", tp="modals-formal"),
      C("You ___ not come if you're busy.", ["need", "must", "should"], "need", "Need not — не обов'язково.", "Need not — не обязательно.", tp="modals-formal"),
      C("All students ___ to wear uniforms.", ["are", "shall", "must"], "are", "Be to — правило.", "Be to — правило.", tp="modals-formal"),
      C("The tenant ___ pay the rent on the first of each month.", ["shall", "would", "might"], "shall", "Документ → shall.", "Документ → shall.", tp="modals-formal"),
      C("How ___ you speak to me like that!", ["dare", "dares", "dared to"], "dare", "How dare you!", tp="modals-formal"),
      C("___ I ask you a personal question?", ["May", "Shall", "Must"], "May", "Офіційний дозвіл → May.", "Официальное разрешение → May.", tp="modals-formal"),
      W(["Shall", "need", "are", "dare"], ["___ we go?", "You ___ not worry.", "You ___ to be here by 8.", "How ___ he!"], ["Shall", "need", "are", "dare"], "Офіційні модальні.", "Официальные модальные.", reuse=False, tp="modals-formal"),
      X("You need not to bring food.", "You need not bring food.", "Need not + дієслово.", "Need not + глагол.", acc=["You needn't bring food.", "You don't need to bring food."], tp="modals-formal"),
      T("Почнімо?", "Начнём?", "Shall we start?", "Shall we.", acc=["Shall we begin?", "Let's start, shall we?"], tp="modals-formal"),
     ]),
   lesson("will and would for habits", "will і would для звичок", "will и would для привычек",
     rule(("will + дієслово — типова (часто дратівлива) звичка зараз · would + дієслово — звичка в минулому · He WILL… (з наголосом) — роздратування", "will + глагол — типичная (часто раздражающая) привычка сейчас · would + глагол — привычка в прошлом · He WILL… (с ударением) — раздражение"),
          "My cat will sleep anywhere — така вже вона. He will keep interrupting! — дратує. When I was a kid, we would go to the village every summer. Would — лише для дій, не для станів: не we would live, а we used to live.",
          "My cat will sleep anywhere — такая уж она. He will keep interrupting! — раздражает. When I was a kid, we would go to the village every summer. Would — только для действий, не для состояний: не we would live, а we used to live.",
          [("She'll talk for hours if you let her.", "Вона може говорити годинами, якщо їй дозволити.", "Она может говорить часами, если ей позволить."),
           ("He will leave his dirty socks on the floor!", "Він постійно залишає брудні шкарпетки на підлозі!", "Он вечно оставляет грязные носки на полу!"),
           ("Every Sunday my grandma would bake pies.", "Щонеділі бабуся пекла пиріжки.", "Каждое воскресенье бабушка пекла пирожки.")]),
     [C("My dog ___ eat anything you give him.", ["will", "would", "shall"], "will", "Типова звичка зараз → will.", "Типичная привычка сейчас → will.", tp="will-would-habits"),
      C("When I was little, my dad ___ read to me every night.", ["would", "will", "was"], "would", "Звичка в минулому → would.", "Привычка в прошлом → would.", tp="will-would-habits"),
      C("We ___ live in a small village. (state)", ["used to", "would", "will"], "used to", "Стан → used to.", "Состояние → used to.", tp="will-would-habits"),
      C("He ___ keep interrupting me! It's so annoying.", ["will", "would", "is"], "will", "Роздратування → will.", "Раздражение → will.", tp="will-would-habits"),
      C("Every summer we ___ swim in the river.", ["would", "will", "were"], "would", "Would.", tp="will-would-habits"),
      M([("She'll sing in the shower.", ("Типова звичка", "Типичная привычка")), ("He WILL leave the door open!", ("Дратує", "Раздражает")), ("We would play outside.", ("Звичка в минулому", "Привычка в прошлом")), ("We used to have a dog.", ("Стан у минулому", "Состояние в прошлом"))], "Значення.", "Значения.", tp="will-would-habits"),
      X("We would have a big house when I was a child.", "We used to have a big house when I was a child.", "Стан → used to.", "Состояние → used to.", tp="will-would-habits"),
      X("My grandpa will tell us stories when we were kids.", "My grandpa would tell us stories when we were kids.", "Минуле → would.", "Прошлое → would.", acc=["My grandpa used to tell us stories when we were kids."], tp="will-would-habits"),
      T("Щоліта ми їздили до бабусі.", "Каждое лето мы ездили к бабушке.", "Every summer we would go to our grandma's.", "Would.", acc=["Every summer we used to go to our grandma's.", "Every summer we would visit our grandma.", "Every summer we used to visit our grandma.", "Every summer we would go to grandma's."], tp="will-would-habits"),
     ]),
  ],
  [C("Don't worry, she's ___ to find out.", ["bound", "unlikely", "possibly"], "bound", "Bound to.", tp="modals-nuance"),
   C("It's ___ to snow in July.", ["unlikely", "bound", "likely"], "unlikely", "Unlikely.", tp="modals-nuance"),
   C("We've missed the film. We might ___ go home.", ["as well", "well", "too"], "as well", "Might as well.", tp="modals-nuance"),
   C("___ we dance?", ["Shall", "Will", "Need"], "Shall", "Shall we.", tp="modals-formal"),
   C("You ___ not apologise.", ["need", "must", "dare"], "need", "Need not.", tp="modals-formal"),
   F("When I was a kid, we ___ play football every day.", "would", "Would.", acc=["used to"], tp="will-would-habits"),
   F("You may ___ be right.", "well", "May well.", tp="modals-nuance"),
   X("We would live in Kharkiv.", "We used to live in Kharkiv.", "Стан → used to.", "Состояние → used to.", tp="will-would-habits"),
   X("I can't possible do it.", "I can't possibly do it.", "Possibly.", tp="modals-nuance"),
   B("All guests are to leave by noon", "Are to → leave.", tp="modals-formal"),
   T("Він неодмінно спізниться.", "Он обязательно опоздает.", "He's bound to be late.", "Bound to.", acc=["He is bound to be late.", "He'll definitely be late.", "He will definitely be late."], tp="modals-nuance"),
   L("He will keep interrupting me.", ["He will keep interrupting me.", "He would keep interrupting me.", "He will keep interpreting me."], "Will keep.", tp="will-would-habits"),
  ], "modals-advanced"))
